import 'package:intl/intl.dart';

final _divisionsProvider =
    FutureProvider.family<List<TournamentDivisionOption>, String>((
      ref,
      tournamentId,
    ) async {
      return ref.read(tournamentRepositoryProvider).getDivisions(tournamentId);
    });

class TournamentRegisterScreen extends ConsumerStatefulWidget {
  final String tournamentId;
  final String? inviteCode;
  final String? divisionId;
  const TournamentRegisterScreen({
    super.key,
    required this.tournamentId,
    this.inviteCode,
    this.divisionId,
  });

  @override
  ConsumerState<TournamentRegisterScreen> createState() =>
      _TournamentRegisterScreenState();
}

class _TournamentRegisterScreenState
    extends ConsumerState<TournamentRegisterScreen> {
  final _formKey = GlobalKey<FormState>();
  final _nameCtrl = TextEditingController();
  final _inviteCtrl = TextEditingController();
  String? _selectedDiv;
  StreamSubscription<Map<String, dynamic>>? _registrationSubscription;
  Timer? _registrationRefreshDebounce;

  @override
  void initState() {
    super.initState();
    if (widget.divisionId != null && widget.divisionId!.isNotEmpty) {
      _selectedDiv = widget.divisionId;
    }
    _checkExistingRegistration();
    _listenForRegistrationUpdates();
  }

  void _listenForRegistrationUpdates() {
    final socket = ref.read(matchSocketServiceProvider);
    _registrationSubscription = socket.onRegistrationUpdate.listen((payload) {
      if (!mounted ||
          payload['tournamentId']?.toString() != widget.tournamentId) {
        return;
      }
      // Socket events are only a hint; providers re-read the authoritative
      // tournament snapshot, so a dropped event is harmless.
      ref.invalidate(tournamentProvider(widget.tournamentId));
      ref.invalidate(tournamentIntroProvider(widget.tournamentId));
      ref.invalidate(_divisionsProvider(widget.tournamentId));
      if (_alreadyRegistered) {
        _registrationRefreshDebounce?.cancel();
        _registrationRefreshDebounce = Timer(
          const Duration(milliseconds: 250),
          () {
            if (mounted) _checkExistingRegistration();
          },
        );
      }
    });
    socket.connect(null, joinMatch: false);
    socket.joinTournament(widget.tournamentId);
  }

  Future<void> _checkExistingRegistration() async {
    try {
      final dio = ref.read(dioProvider);
      // Truy vấn theo CẢ GIẢI (không lọc `?divisionId`): card "Đã đăng ký" là
      // GLOBAL (`if (_alreadyRegistered)` chiếm toàn màn hình, không theo tab).
      // Nếu lọc theo divisionId của tab đang xem, thì khi intro mở bằng
      // `?divisionId=<tab khác division đã đăng ký>` → backend trả registered:false
      // → app hiện form thay vì status card → mất nghiệp vụ "duyệt chưa / rút lui".
      // (khớp web: luôn show trạng thái đăng ký dù vào từ tab nào). fix #34
      final response = await dio.get(
        '/tournaments/${widget.tournamentId}/my-registration',
      );
      final raw = response.data;
      final payload = raw is Map && raw['data'] is Map ? raw['data'] : raw;
      final participant = payload is Map && payload['participant'] is Map
          ? payload['participant'] as Map
          : null;
      if (payload is Map &&
          payload['registered'] == true &&
          participant != null) {
        final status = participant['teamStatus']?.toString();
        const closedStatuses = {'WITHDRAWN', 'REJECTED', 'KICKED', 'EXPIRED'};
        if (closedStatuses.contains(status)) {
          if (mounted) {
            setState(() {
              _alreadyRegistered = false;
              _checkingRegistration = false;
            });
          }
          return;
        }
        if (mounted) {
          setState(() {
            _alreadyRegistered = true;
            _existingParticipantId = participant['id']?.toString();
            _existingDivisionId = participant['tournamentDivisionId']
                ?.toString();
            _existingTeamStatus = status;
            _existingIsPaid = participant['isPaid'] == true;
            _existingPaymentEligible = payload['paymentEligible'] == true;
            _checkingRegistration = false;
          });
        }
        return;
      }
    } catch (_) {}
    if (mounted) setState(() => _checkingRegistration = false);
  }

  String? _divisionError;
  bool _submitting = false;
  bool _success = false;
  AppLocalizations get l10n => AppLocalizations.of(context)!;

  String _formatAmount(num amount) => NumberFormat.decimalPattern(
    Localizations.localeOf(context).toLanguageTag(),
  ).format(amount.ceil());

  String _formatFee(num amount) =>
      '${_formatAmount(amount)}${l10n.registerFeeUnit}';

  String? _genderError;
  String? _eloError;
  bool _eloChecking = false;
  bool _inviteValidating = false;
  String? _inviteError;
  String? _localInviteCode;
  double? _registeredEntryFee;
  TournamentDivisionOption? _registeredDivision;
  String? _registrationTeamStatus;
  bool _checkingRegistration = true;
  bool _alreadyRegistered = false;
  String? _existingParticipantId;
  String? _existingDivisionId;
  String? _existingTeamStatus;
  bool _existingIsPaid = false;
  bool _existingPaymentEligible = false;

  bool _rankingConsent = false;
  final Map<String, dynamic> _customResponses = {};

  String _getSubmitLabel(Tournament? t) {
    if (t?.registrationMode == 'APPROVAL') return l10n.registerSubmitApproval;
    return l10n.registerSubmitConfirm;
  }

  List<Map<String, dynamic>> _activeRegistrationFields(Tournament tournament) {
    final divisionId = _selectedDiv;
    if (divisionId == null || divisionId.isEmpty) return const [];
    if (tournament.registrationFormDivisionIds.isNotEmpty &&
        !tournament.registrationFormDivisionIds.contains(divisionId)) {
      return const [];
    }

    return tournament.registrationFields;
  }

  String? _validateCustomResponses(Tournament tournament) {
    for (final field in _activeRegistrationFields(tournament)) {
      final id = field['id']?.toString() ?? '';
      final value = _customResponses[id];
      final empty =
          value == null ||
          value.toString().trim().isEmpty ||
          (value is List && value.isEmpty);
      final label = field['label']?.toString() ?? id;
