class DoublesRegistrationMember {
  const DoublesRegistrationMember({required this.fullName, required this.role});

  final String fullName;
  final String role;

  factory DoublesRegistrationMember.fromJson(Map<dynamic, dynamic> json) {
    return DoublesRegistrationMember(
      fullName: json['fullName']?.toString().trim() ?? '',
      role: json['role']?.toString().trim().toUpperCase() ?? '',
    );
  }

  static List<DoublesRegistrationMember> fromParticipantJson(Object? value) {
    if (value is! Map) return const [];

    final members = value['members'];
    final teamMembers = value['teamMembers'];
    final raw = members is List && members.isNotEmpty ? members : teamMembers;
    if (raw is! List) return const [];

    return raw
        .whereType<Map>()
        .map(DoublesRegistrationMember.fromJson)
        .where((member) => member.fullName.isNotEmpty)
        .toList(growable: false);
  }
}

  Widget _buildExistingRegistration(
    Tournament tournament,
    List<TournamentDivisionOption> divisions,
  ) {
    TournamentDivisionOption? existingDivision;
    for (final division in divisions) {
      if (division.id == _existingDivisionId) {
        existingDivision = division;
        break;
      }
    }

    final fee = existingDivision?.entryFee ?? tournament.entryFee ?? 0;
    final status = _existingTeamStatus ?? '';
    final isPendingApproval = status == 'PENDING_APPROVAL';
    final isPendingPartner = status == 'PENDING_PARTNER';
    final isWaitlisted = status == 'WAITLISTED';
    final isComplete = status == 'COMPLETE' || status == 'CONFIRMED' || status == 'APPROVED';
    final canPay = !_existingIsPaid &&
        fee > 0 &&
        (_existingPaymentEligible || isComplete) &&
        !isWaitlisted &&
        !isPendingApproval &&
        !isPendingPartner;

    final statusLabel = switch (status) {
      'PENDING_PARTNER' => l10n.registerStatusPendingPartner,
      'PENDING_APPROVAL' => l10n.registerStatusPendingApproval,
      'WAITLISTED' => l10n.registerStatusWaitlisted,
      'COMPLETE' when _existingIsPaid => l10n.registerStatusCompletePaid,
      'COMPLETE' => l10n.registerStatusCompleteUnpaid,
      _ => l10n.registerAlreadyRegistered,
    };

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(24),
      decoration: BoxDecoration(
        color: context.colors.bgCard,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: context.colors.border),
      ),
      child: Column(
        children: [
          Icon(
            _existingIsPaid ? Icons.verified_rounded : Icons.how_to_reg_rounded,
            size: 52,
            color: _existingIsPaid ? context.colors.success : AppTheme.primary,
          ),
          const SizedBox(height: 16),
          Text(
            statusLabel,
            textAlign: TextAlign.center,
            style: TextStyle(
              color: context.colors.textPrimary,
              fontSize: 18,
              fontWeight: FontWeight.w800,
            ),
          ),
          if (isPendingApproval) ...[
            const SizedBox(height: 12),
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
              decoration: BoxDecoration(
                color: Colors.amber.withValues(alpha: 0.12),
                borderRadius: BorderRadius.circular(10),
                border: Border.all(color: Colors.amber.withValues(alpha: 0.3)),
              ),
              child: Row(
                children: [
                  const Icon(Icons.info_outline_rounded, color: Colors.amber, size: 20),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Text(
                      'Đơn đăng ký đang chờ Ban Tổ Chức xét duyệt. Nút thanh toán sẽ hiển thị sau khi BTC phê duyệt.',
                      style: TextStyle(
                        fontSize: 12.5,
                        color: context.colors.textPrimary,
                        height: 1.35,
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ],
          if (isPendingPartner) ...[
            const SizedBox(height: 12),
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
              decoration: BoxDecoration(
                color: AppTheme.primary.withValues(alpha: 0.1),
                borderRadius: BorderRadius.circular(10),
                border: Border.all(color: AppTheme.primary.withValues(alpha: 0.3)),
              ),
              child: Row(
                children: [
                  const Icon(Icons.group_add_rounded, color: AppTheme.primary, size: 20),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Text(
                      'Đang chờ đồng đội tham gia. Sau khi đồng đội vào đội, bạn có thể thanh toán lệ phí.',
                      style: TextStyle(
                        fontSize: 12.5,
                        color: context.colors.textPrimary,
                        height: 1.35,
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ],
          if (isWaitlisted) ...[
            const SizedBox(height: 12),
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 10),
              decoration: BoxDecoration(
                color: Colors.orange.withValues(alpha: 0.12),
                borderRadius: BorderRadius.circular(10),
                border: Border.all(color: Colors.orange.withValues(alpha: 0.3)),
              ),
              child: Row(
                children: [
                  const Icon(Icons.hourglass_top_rounded, color: Colors.orange, size: 20),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Text(
                      l10n.registerNoPaymentWaitlisted,
                      style: TextStyle(
                        fontSize: 12.5,
                        color: context.colors.textPrimary,
                        height: 1.35,
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ],
          if (existingDivision != null) ...[
            const SizedBox(height: 12),
            _buildRegistrationDetails(
              existingDivision,
              status,
              _existingIsPaid,
            ),
          ],
          if (status == 'PENDING_PARTNER') ...[
            const SizedBox(height: 16),
            SizedBox(
              width: double.infinity,
              child: FilledButton.icon(
                onPressed: () {
                  final inviteCode =
                      _localInviteCode ?? widget.inviteCode ?? '';
                  context.push(
                    '/register/${widget.tournamentId}/doubles?divisionId=${_existingDivisionId ?? ''}&invite=$inviteCode',
                    extra: existingDivision,
                  );
                },
                icon: const Icon(Icons.qr_code_rounded),
                label: Text(l10n.registerViewInviteCode),
              ),
            ),
          ],
          if (canPay) ...[
            const SizedBox(height: 20),
            SizedBox(
              width: double.infinity,
              height: 48,
              child: FilledButton.icon(
                onPressed: () => context.push(
                  '/payment/checkout',
                  extra: {
                    'tournamentId': tournament.id,
                    'participantId': _existingParticipantId,
                    'divisionId': _existingDivisionId,
                    'amount': fee,
                    'tournamentName': tournament.name,
                  },
                ),
                icon: const Icon(Icons.payment_rounded),
                label: Text(
                  l10n.registerPayNow(_formatAmount(fee)),
                  style: const TextStyle(fontWeight: FontWeight.w800, fontSize: 15),
                ),
              ),
            ),
          ],
          const SizedBox(height: 12),
          OutlinedButton.icon(
            onPressed: () async {
              final withdrew = await WithdrawSheet.show(
                context,
                tournamentId: tournament.id,
                divisionId: _existingDivisionId,
                hasPaid: _existingIsPaid && fee > 0,
              );
              if (!withdrew || !mounted) return;
              context.go('/intro/${tournament.id}');
            },
            icon: Icon(Icons.exit_to_app_rounded, color: context.colors.error),
            label: Text(
              l10n.registerWithdraw,
…
            ),
          ),
…
        ],
      ),
    );
  }

